<script setup lang="ts">import {useVbenModal} from '@vben/common-ui';import {useVbenForm} from '#/adapter/form';import {studioApi} from '#/api/studio';const emit=defineEmits(['success']);const [Form,formApi]=useVbenForm({layout:'vertical',showDefaultActions:false,schema:[{component:'Input',fieldName:'name',label:'分类名称',rules:'required'}]});const [Modal,modalApi]=useVbenModal({async onConfirm(){const {valid}=await formApi.validate();if(!valid)return;modalApi.lock();try{const v=await formApi.getValues();await studioApi.addCategory(v.name);modalApi.close();emit('success')}finally{modalApi.lock(false)}},onOpenChange(open){if(open)formApi.reset()}});defineExpose({modalApi});</script><template><Modal title="新增分类"><Form/></Modal></template>
